/* 生成的图层（见 assets/prompts/），已裁切、压缩，作为 data URI 放进页面。 */
(() => { const A = (window.YL.ASSET_DATA = window.YL.ASSET_DATA || {});
A["paper_watercolor"] = "data:image/jpeg;base64,";
A["paper_washi"] = "data:image/jpeg;base64,";
A["paper_xuan"] = "data:image/jpeg;base64,";
A["paper_canvas"] = "data:image/jpeg;base64,";
(window.YL.ASSET_SIZE = window.YL.ASSET_SIZE || {}); Object.assign(window.YL.ASSET_SIZE, {"paper_watercolor": [1024, 1024], "paper_washi": [1024, 1024], "paper_xuan": [1024, 1024], "paper_canvas": [1024, 1024]});
})();
